l1 = [1, 3, 2, 5]
l2 = [1, 2, 6, 3]

d1 = {}
for k,v in zip(l1,l2):
    if k%2 == 0 or v%2 == 0:
        continue
    d1[k] = v * 3
print(d1)

d1 = {k: v*3 for k,v in zip(l1,l2) if not (k%2 == 0 or v%2 == 0)}
print(d1)

l1 = [1, 3, 2, 5] 

s1 = set()
for x in l1:
    if x % 2 == 0:
        continue
    s1.add(x * 2)
print(s1)

s1 = {x * 2 for x in l1 if not (x%2 == 0)}
print(s1)

func = lambda x,y: x+y

result = {}
for x in range(1, 4):
    result1 = {}
    for y in range(x, 4):
        result1[y] = func(x,y)
    result[x] = result1    
print(result)
print(result[2][3])

del x, y
result = {x:{y: func(x,y) for y in range(x, 4)} for x in range(1, 4)}
print(result)
print(result[2][3])

func = lambda x,y: x+y

result = {}
for x in range(1, 4):
    for y in range(x, 4):
        result[x,y] = func(x,y)
