class Myiterator:
    def __init__(self, start, stop, step):
        self.start = start
        self.stop = stop
        self.step = step
    def __iter__ (self):
        return self
    def __next__(self):
        self.num = self.start
        self.start += self.step
        if self.num > self.stop:
            raise StopIteration('End of numbers')
        else:
            return self.num
for x in Myiterator(1, 5, 2):
    print(x)

class Myiterator:
    def __init__(self, start, stop, step):
        self.start = start
        self.stop = stop
        self.step = step
    def __next__(self):
        self.num = self.start
        self.start += self.step
        if self.num > self.stop:
            raise StopIteration('End of numbers')
        else:
            return self.num
myiterator = Myiterator(1, 5, 2)
for x in myiterator:
    print(x)

def generatorfunction(start, stop, step):
    while (num:=start) <= stop:
        yield num
        start += step
    return 'End of numbers'
for x in generatorfunction(1, 5, 2):
    print(x)

def generatorfunction(start, stop, step):
    while True:
        num = start
        start += step
        if num <= stop:
            yield num
        else:
            return 'End of numbers'
print(list(generatorfunction(1, 5, 2)))

